begin;
do $$
declare a uuid:='92300000-0000-4000-8000-000000000001'; b uuid:='92300000-0000-4000-8000-000000000002'; c uuid:='92300000-0000-4000-8000-000000000003'; creator uuid:='92300000-0000-4000-8000-000000000010'; quiz uuid:='92300000-0000-4000-8000-000000000011'; target uuid; attempt uuid; pass uuid; job uuid; passport uuid; conversation uuid; message_id uuid; result jsonb; settings jsonb; friend uuid; post_id uuid; comment_id uuid; n uuid; n2 uuid; d uuid; old_count integer; begin
 insert into public.app_users(id,privy_user_id,verified_email) values(a,'did:privy:social-notification-a','social-notification-a@example.test'),(b,'did:privy:social-notification-b','social-notification-b@example.test'),(c,'did:privy:social-notification-c','social-notification-c@example.test');
 insert into public.celebrities(id,slug,status,image_url,published_at,roles,primary_role) values(creator,'social-notification-creator','published','/social.webp',now(),'{creator}','creator');
 insert into public.celebrity_localizations(celebrity_id,locale,name,summary,image_alt) values(creator,'ko','소셜','소개','소셜'),(creator,'en','Social','Summary','Social');
 insert into public.celebrity_quizzes(id,celebrity_id,version,status) values(quiz,creator,1,'draft');
 alter table public.fan_passports disable trigger fan_passports_validate_blockchain_job_link;
 foreach target in array array[a,b] loop
   attempt:=extensions.gen_random_uuid(); pass:=extensions.gen_random_uuid(); job:=extensions.gen_random_uuid(); passport:=extensions.gen_random_uuid();
   insert into public.quiz_attempts(id,app_user_id,celebrity_id,quiz_id,quiz_version,idempotency_key,status,score,submitted_at) values(attempt,target,creator,quiz,1,extensions.gen_random_uuid(),'passed',3,now());
   insert into public.quiz_passes(id,app_user_id,celebrity_id,winning_attempt_id) values(pass,target,creator,attempt);
   insert into public.blockchain_jobs(id,entity_type,entity_id,operation_key,payload) values(job,'passport',passport,'social-notification-passport-'||passport::text,'{}');
   insert into public.fan_passports(id,app_user_id,celebrity_id,quiz_pass_id,blockchain_job_id) values(passport,target,creator,pass,job);
 end loop;
 alter table public.fan_passports enable trigger fan_passports_validate_blockchain_job_link;

 perform public.set_owned_social_settings(a,true,array['social-notification-creator'],'requests');
 perform public.set_owned_social_settings(b,true,array['social-notification-creator'],'requests');
 settings:=public.mobile_get_owned_settings(a);
 if settings#>>'{previews,0,kind}' is distinct from 'news' or settings#>>'{previews,0,name}' is distinct from '소셜' then raise exception 'actual favorite preview missing: %',settings; end if;
 perform public.mobile_register_owned_installation(b,'92300000-0000-4000-8000-000000000801','ios','social-test-token','authorized','1.0.0','ko',0,'92300000-0000-4000-8000-000000000802');
 insert into public.user_profiles(app_user_id,nickname,nickname_normalized) values(a,'요청한팬','요청한팬');
 result:=public.request_social_friend(a,b,'social-notification-creator','92300000-0000-4000-8000-000000000101'); friend:=(result->>'id')::uuid;
 perform public.request_social_friend(a,b,'social-notification-creator','92300000-0000-4000-8000-000000000101');
 if (select count(*) from public.fan_web_notification_intents where recipient_app_user_id=b and kind='fan_friend_request') is distinct from 1 then raise exception 'friend replay duplicated intent'; end if;
 perform public.fan_web_drain_notification_intents(b);
 update public.fan_notifications set scheduled_for=now()-interval '1 second' where app_user_id=b;
 select id into n from public.fan_notifications where app_user_id=b and kind::text='fan_friend_request';
 if public.fan_web_notification_path(b,n) is distinct from ('/people/'||a||'/friend-request?favorite=social-notification-creator') or public.fan_web_notification_path(c,n) is not null then raise exception 'friend request owner path invalid'; end if;
 if public.mobile_get_owned_notification(b,n,'ko')->>'subject' is distinct from '요청한팬' or public.mobile_get_owned_notification(c,n,'ko') is not null then raise exception 'owned request sender projection invalid'; end if;
 if exists(select 1 from public.notification_delivery_outbox where notification_id=n) or exists(select 1 from public.external_notification_delivery_outbox where notification_id=n) then raise exception 'private social notification escaped to legacy external delivery'; end if;
 perform public.mobile_claim_push_deliveries('social-worker',100,60);
 select id into d from public.mobile_push_delivery_outbox where notification_id=n;
 result:=public.mobile_prepare_push_delivery(d,'social-worker');
 if result is null or (select count(*) from jsonb_object_keys(result->'payload')) is distinct from 3 or result#>>'{payload,category}' is distinct from 'community' then raise exception 'private push payload invalid: %',result; end if;
 perform public.block_social_profile(b,a,extensions.gen_random_uuid());
 if public.fan_web_notification_path(b,n) is not null or public.mobile_prepare_push_delivery(d,'social-worker') is not null then raise exception 'blocked request remained deliverable'; end if;
 perform public.unblock_social_profile(b,a);
 -- A new request can be exercised independently of the cooldown left by the block.
 update public.social_friendships set retry_at=null where id=friend;
 result:=public.request_social_friend(a,b,'social-notification-creator',extensions.gen_random_uuid()); friend:=(result->>'id')::uuid;
 perform public.resolve_social_friend(b,friend,'accept',extensions.gen_random_uuid());
 if public.fan_web_notification_path(b,n) is not null then raise exception 'old request revived after a new relationship'; end if;
 result:=public.request_social_dm(a,b,'never expose this message',extensions.gen_random_uuid()); conversation:=(result->>'id')::uuid;
 message_id:=(result->>'firstMessageId')::uuid;
 perform public.fan_web_drain_notification_intents(b);
 update public.fan_notifications set scheduled_for=now()-interval '1 second' where app_user_id=b;
 select id into n from public.fan_notifications where app_user_id=b and kind::text='fan_dm_message' and payload->>'targetId'=message_id::text;
 if public.fan_web_notification_path(b,n) is distinct from ('/messages/'||conversation) or (select payload::text like '%never expose%' from public.fan_notifications where id=n) then raise exception 'DM notification path/payload invalid'; end if;
 perform public.resolve_social_friend(a,friend,'unfriend',extensions.gen_random_uuid());
 if public.fan_web_notification_path(b,n) is not null then raise exception 'DM notification survived last friend removal'; end if;
 update public.social_dm_conversations set retry_at=null where id=conversation;
 result:=public.request_social_dm(a,b,'private message request',extensions.gen_random_uuid());
 message_id:=(result->>'firstMessageId')::uuid;
 perform public.fan_web_drain_notification_intents(b);
 update public.fan_notifications set scheduled_for=now()-interval '1 second' where app_user_id=b;
 select id into n from public.fan_notifications where app_user_id=b and kind::text='fan_dm_request' and payload->>'targetId'=message_id::text;
 if public.fan_web_notification_path(b,n) is distinct from ('/messages/'||conversation) then raise exception 'DM request notification missing'; end if;
 perform public.resolve_social_dm(b,conversation,'reject',extensions.gen_random_uuid());
 if public.fan_web_notification_path(b,n) is not null then raise exception 'rejected DM request remained visible'; end if;
 update public.social_friendships set retry_at=null where requester_id=a and addressee_id=b;
 result:=public.request_social_friend(a,b,'social-notification-creator',extensions.gen_random_uuid()); friend:=(result->>'id')::uuid;
 perform public.resolve_social_friend(b,friend,'accept',extensions.gen_random_uuid());
 result:=public.save_fan_post(a,'social-notification-creator',null,'friend post','public','{}',null,extensions.gen_random_uuid()); post_id:=(result->>'id')::uuid;
 perform public.fan_web_drain_notification_intents(b);
 update public.fan_notifications set scheduled_for=now()-interval '1 second' where app_user_id=b;
 select id into n from public.fan_notifications where app_user_id=b and kind::text='friend_post' and payload->>'targetId'=post_id::text;
 if public.fan_web_notification_path(b,n) is distinct from ('/c/social-notification-creator/community/'||post_id) then raise exception 'friend post notification missing'; end if;
 perform public.set_fan_post_like(b,post_id,true); perform public.set_fan_post_like(b,post_id,true);
 perform public.fan_web_drain_notification_intents(a);
 update public.fan_notifications set scheduled_for=now()-interval '1 second' where app_user_id=a;
 select id into n2 from public.fan_notifications where app_user_id=a and kind::text='friend_reaction';
 if public.fan_web_notification_path(a,n2) is distinct from ('/c/social-notification-creator/community/'||post_id) or (select count(*) from public.fan_notifications where app_user_id=a and kind::text='friend_reaction') is distinct from 1 then raise exception 'friend reaction missing or duplicated'; end if;
 perform public.set_fan_post_like(b,post_id,false);
 if public.fan_web_notification_path(a,n2) is not null then raise exception 'removed reaction remained visible'; end if;
 result:=public.post_fan_post_comment(a,post_id,null,'my comment',extensions.gen_random_uuid()); comment_id:=(result->>'id')::uuid;
 perform public.set_mobile_content_comment_reaction(b,'fan_post_comment',comment_id,'❤');
 perform public.fan_web_drain_notification_intents(a);
 update public.fan_notifications set scheduled_for=now()-interval '1 second' where app_user_id=a;
 select id into n2 from public.fan_notifications where app_user_id=a and kind::text='friend_reaction' and payload->>'targetType'='fan_post_comment_reaction';
 if public.fan_web_notification_path(a,n2) is null then raise exception 'friend comment reaction missing'; end if;
 update public.fan_posts set hidden_at=now() where id=post_id;
 if public.fan_web_notification_path(b,n) is not null or public.fan_web_notification_path(a,n2) is not null then raise exception 'hidden post/reaction remained visible'; end if;
 settings:=public.mobile_get_owned_settings(b);
 perform public.mobile_patch_owned_settings(b,(settings->>'revision')::bigint,'{"topics":{"friendActivity":false,"social":false}}');
 select count(*) into old_count from public.fan_notifications where app_user_id=b;
 perform public.save_fan_post(a,'social-notification-creator',null,'muted friend post','public','{}',null,extensions.gen_random_uuid());
 update public.social_dm_conversations set status='accepted' where id=conversation;
 perform public.send_social_dm_message(a,conversation,'muted private message',extensions.gen_random_uuid());
 perform public.fan_web_drain_notification_intents(b);
 update public.fan_notifications set scheduled_for=now()-interval '1 second' where app_user_id=b;
 if (select count(*) from public.fan_notifications where app_user_id=b) is distinct from old_count then raise exception 'muted social topics materialized'; end if;
 if public.mobile_notification_category('live_reserved') is distinct from 'schedule' then raise exception 'reservation category invalid'; end if;
 if has_function_privilege('anon','public.mobile_social_notification_path(uuid,text,text,uuid)','EXECUTE') or has_function_privilege('service_role','public.mobile_enqueue_social_notification()','EXECUTE') or has_function_privilege('service_role','public.fan_web_notification_path_before_social(uuid,uuid)','EXECUTE') then raise exception 'private helper exposed'; end if;
end $$;
rollback;
